      "area": "인공지능과 학습",
      "family": "고려사항",
      "sectionTitle": "고려사항",
      "sourceText": "기계학습과 딥러닝을 구현하는 과정에서 학습자의 수준에 따라 코드 작성의 방식을 달리 구성할 수 있다. 프로그래밍 역량이 낮은 학생은 이미 작성된 코드를 실행시켜 코드를 이해한 후 차츰 코드 일부를 수정하는 방식으로 학습할 수 있도록 하고, 프로그래밍 역량이 높은 학생은 작성이 완료되지 않은 코드를 스스로 완성하여 실행시킬 수 있도록 하는 등 교수⋅학습 단계를 세부적으로 구성하여 학습자의 흥미가 유지되도록 한다. 또한, 기계학습과 딥러닝을 코드로 구현하는 학습을 원활하게 진행하기 위해, 다양한 라이브러리 활용 방법을 충분히 안내한다.",
      "sourceDoc": "교육부 고시 제2022-33호 [별책 10] 정보과 교육과정 - 인공지능 기초",
