      "family": "고려사항",
      "sectionTitle": "고려사항",
      "sourceText": "인공지능과 관련한 윤리적 쟁점 사례를 조사하고, 구체적인 사안을 주제로 하는 토론 활동의 과정에서 인공지능 윤리의 중요성과 인공지능과 인간의 관계를 올바르게 설명할 수 있는지를 평가하도록 한다. 이 과정에서 근거를 바탕으로 자신의 주장을 펼치고 타인의 견해를 존중하는 성숙한 토론 문화를 조성하도록 한다.",
