      "family": "고려사항",
      "sectionTitle": "고려사항",
      "sourceText": "인공지능 프로젝트를 위한 주제 선정 과정에서 인류가 직면해 있는 다양한 위기를 충분히 인식할 수 있도록 하고, 이러한 위기를 극복하는 다양한 방법 중 하나로 인공지능이 중요한 역할을 수행할 수 있다는 점을 강조하도록 한다. 또한, 인공지능을 활용하는 방법적인 측면에서 직접 구현하기가 어려운 부분이 있더라도 학습자의 아이디어를 존중하여 다양한 생각이 발산될 수 있는 활동을 구성하도록 한다.",
